<script setup lang="ts">
import {onMounted,onBeforeUnmount,ref} from 'vue';
import {useRoute} from 'vue-router';
import {api,apiBlob} from '../services/api';
import AppHeader from '../components/AppHeader.vue';
import EvidenceViewer from '../components/EvidenceViewer.vue';
const route=useRoute(),id=String(route.params.id),document=ref<any>(null),scan=ref<any>(null),selected=ref<string[]>([]),consent=ref(false),busy=ref(false),error=ref(''),copy=ref<any>(null),copyUrl=ref('');
onMounted(async()=>{try{document.value=await api('/api/v1/documents/'+id)}catch(e:any){error.value=e.message}});
onBeforeUnmount(()=>{if(copyUrl.value)URL.revokeObjectURL(copyUrl.value)});
async function detect(){busy.value=true;error.value='';try{scan.value=await api(`/api/v1/documents/${id}/privacy/scan`,{method:'POST'});selected.value=[];consent.value=false}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function redact(){if(!scan.value||!consent.value)return;busy.value=true;error.value='';try{copy.value=await api(`/api/v1/documents/${id}/redact`,{method:'POST',body:JSON.stringify({revision:scan.value.revision,finding_ids:selected.value,consent:true})});const blob=await apiBlob(`/api/v1/document-copies/${copy.value.id}/content`);if(copyUrl.value)URL.revokeObjectURL(copyUrl.value);copyUrl.value=URL.createObjectURL(blob)}catch(e:any){error.value=e.message}finally{busy.value=false}}
</script>
<template><div class="page page--utility"><AppHeader title="文件隐私与脱敏"/><p v-if="error" class="notice notice--danger" role="alert">{{error}}</p><template v-if="document"><h2>{{document.name}}</h2><p>原件保留不变，当前区域遮盖按整行处理。未标注姓名、地址和二维码仍需人工核对。</p><EvidenceViewer :evidence="{document_id:id,page:1,preview_available:['image/png','image/jpeg','application/pdf'].includes(document.mime)}"/><button class="button button--secondary" :disabled="busy" @click="detect">扫描敏感内容</button><section v-if="scan" class="surface-card"><p>内部风险提示 {{scan.risk_score}}/100（启发式分数，不是概率）</p><label v-for="finding in scan.findings" :key="finding.id" class="consent-row"><input v-model="selected" type="checkbox" :value="finding.id">{{finding.label}} · {{finding.page?'第'+finding.page+'页':'文字定位'}} · {{finding.location_quality==='line'?'将遮盖整行':'没有区域坐标'}} · {{finding.preview}}</label><p v-if="!scan.findings.length">当前规则未检测到支持的格式，这不代表绝对安全。</p><label class="consent-row"><input v-model="consent" type="checkbox">我已核对所选区域，同意生成脱敏副本。</label><button class="button button--primary" :disabled="busy||!selected.length||!consent" @click="redact">生成永久脱敏副本</button></section><section v-if="copyUrl" class="surface-card"><img v-if="copy.mime==='image/png'" :src="copyUrl" alt="脱敏副本" style="max-width:100%"><p>已生成副本，请下载后再次人工检查。</p><a class="button button--primary" :href="copyUrl" :download="`privacy-safe.${copy.mime==='image/png'?'png':'pdf'}`">下载脱敏副本</a></section></template></div></template>
